CREATE OR REPLACE FUNCTION public.ajustar_stock(p_variante_id uuid, p_delta integer, p_motivo text, p_usuario_id uuid, p_permitir_negativo boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_stock_actual int; v_stock_nuevo int; v_usuario_email text; v_producto_id uuid; v_producto_nombre text; v_variante_sku text; v_empresa_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'No autenticado'; END IF; IF auth.uid() <> p_usuario_id THEN RAISE EXCEPTION 'p_usuario_id no coincide con el usuario autenticado'; END IF; IF p_motivo IS NULL OR trim(p_motivo) = '' THEN RAISE EXCEPTION 'El motivo es obligatorio'; END IF; SELECT empresa_id INTO v_empresa_id FROM public.usuarios WHERE id = p_usuario_id AND activo = true; IF NOT FOUND THEN RAISE EXCEPTION 'Usuario no encontrado o inactivo'; END IF; IF v_empresa_id IS NULL THEN RAISE EXCEPTION 'Usuario sin empresa asignada'; END IF; SELECT v.stock, v.producto_id, v.sku_variante, p.nombre INTO v_stock_actual, v_producto_id, v_variante_sku, v_producto_nombre FROM public.variantes v JOIN public.productos p ON p.id = v.producto_id WHERE v.id = p_variante_id AND v.empresa_id = v_empresa_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'La variante no existe o no pertenece a la empresa'; END IF; v_stock_nuevo := v_stock_actual + p_delta; IF NOT p_permitir_negativo AND v_stock_nuevo < 0 THEN RAISE EXCEPTION 'Stock no puede quedar negativo (actual: %, ajuste: %)', v_stock_actual, p_delta; END IF; UPDATE public.variantes SET stock = v_stock_nuevo WHERE id = p_variante_id AND empresa_id = v_empresa_id; BEGIN SELECT email INTO v_usuario_email FROM public.usuarios WHERE id = p_usuario_id; INSERT INTO public.audit_log (usuario_id, usuario_email_snapshot, entidad, entidad_id, accion, detalle, empresa_id) VALUES (p_usuario_id, COALESCE(v_usuario_email, 'desconocido'), 'variantes', p_variante_id, 'ajustar_stock', jsonb_build_object('producto_nombre', v_producto_nombre, 'variante_sku', v_variante_sku, 'stock_anterior', v_stock_actual, 'delta', p_delta, 'stock_nuevo', v_stock_nuevo, 'motivo', p_motivo, 'permitir_negativo', p_permitir_negativo), v_empresa_id); EXCEPTION WHEN OTHERS THEN NULL; END; RETURN jsonb_build_object('ok', true, 'stock_anterior', v_stock_actual, 'stock_nuevo', v_stock_nuevo); END; $function$; REVOKE EXECUTE ON FUNCTION public.ajustar_stock(uuid, integer, text, uuid, boolean) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.ajustar_stock(uuid, integer, text, uuid, boolean) TO authenticated; DROP FUNCTION IF EXISTS public.ajustar_stock(uuid, integer, text, uuid); COMMENT ON FUNCTION public.ajustar_stock(uuid, integer, text, uuid, boolean) IS 'Ajusta stock de una variante. p_permitir_negativo=true permite quedar bajo cero (caso edicion de venta cerrada).';
